    <SearchPalette ref="search" @ai-complete="showAiCompletion" />
    <teleport to="body">
      <transition name="ai-ready">
        <aside
          v-if="showViewJobNotice"
          class="ai-ready-notice ai-compose-notice"
        >
          <button
            class="ai-compose-notice-button"
            type="button"
            aria-label="Open View composition progress"
            @click="openActiveViewJob"
          >
            <ViewComposeProgress compact :started-at="viewJobNotice.startedAt" />
          </button>
        </aside>
      </transition>
      <transition name="ai-ready">
        <aside
          v-if="aiCompletion"
          class="ai-ready-notice"
