<script>
import SearchPalette from './components/SearchPalette.vue';
import SourceViewLinks from './components/ui/SourceViewLinks.vue';
import AiViewTerm from './components/ui/AiViewTerm.vue';
import ViewComposeProgress from './components/view/ViewComposeProgress.vue';
import { initCircularMediaRails } from './utils/mediaRails';
import {
  addAskTurn,
  clearSiteOrigin,
  consumeTabNavigation,
  loadAskSession,
  getSiteOrigin,
  markTabNavigation,
  setPendingViewReturnScroll,
  setAskOrigin,
  setAskView,
  setSiteOrigin,
  setViewOriginRoute,
} from './utils/askSession';
import { candidatesForView } from './utils/viewRetrieval';
import { sanitizeViewResponse, validateViewResponse } from './utils/viewValidation';
import { clearViewJob, loadViewJob, resumeViewJob } from './utils/viewSite';
import { settleScrollToY } from './utils/anchorLanding';
import { animate } from 'motion';

// The dock elements only ever translate (resting transforms are pure
// translateY), so the live on-screen offset is just the matrix translation.
function currentTranslation(element) {
  try {
    const m = new DOMMatrix(getComputedStyle(element).transform);
    return { x: m.m41, y: m.m42 };
  } catch (e) {
    return { x: 0, y: 0 };
  }
}

function isGeneratedViewPath(path) {
  const value = String(path || '');
  return value === '/view' || value.startsWith('/view/');
}

function siteOriginLabel(from) {
  if (from.path === '/' || from.path === '/home') return 'Home';
  if (from.path === '/projects') return 'Builds';
  const meta = String((from.meta && from.meta.title) || '');
  const name = meta.replace(/\s*-\s*H\.W\.\s*$/, '').trim();
  return name || (String(from.path).split('/').filter(Boolean).pop() || 'Home');
}

export default {
  name: 'App',
  components: { AiViewTerm, SearchPalette, SourceViewLinks, ViewComposeProgress },
  data() {
    return {
      scrollPct: 0,
      navTabsLayout: 'one',
      cvChromeHidden: false,
      footerCompassSpin: '',
      marginDockActive: false,
      marginDockPinned: false,
      dockHoverCount: 0,
      dockThemeIconClass: 'fa fa-moon',
      dockThemeLabel: 'Toggle theme',
      dockMusicIconClass: 'fa fa-compact-disc',
      dockMusicLabel: 'Play music',
      directHomeNavHidden: false,
      initialChromeReady:
        typeof window === 'undefined'
        || /^#\/(?:$|home(?:$|[?#]))/.test(window.location.hash || ''),
      viewOriginCache: [],
      viewReturnTarget: '',
      viewReturnScrollY: 0,
      siteBackTarget: '',
      siteBackLabel: '',
      siteBackScrollY: 0,
      aiCompletion: null,
      viewJobNotice: null,
      viewProgressInlineCount: 0,
      mobileMenuOpen: false,
    };
  },
  computed: {
    previewMode() {
      return this.$route.query.preview === '1';
    },
    isIntroRoot() {
      return this.$route.path === '/';
    },
    isHomeRoute() {
      return this.$route.path === '/' || this.$route.path === '/home';
    },
    isCv() {
      return this.$route.path === '/cv';
    },
    isGeneratedViewRoute() {
      return isGeneratedViewPath(this.$route.path);
    },
    showScrollProgress() {
      return !this.isCv && this.$route.path !== '/home' && this.$route.path !== '/';
    },
    showViewJobNotice() {
      return !!this.viewJobNotice && this.viewProgressInlineCount === 0;
    },
    detailSourceId() {
      return {
        '/playbook': 'projects:insurance',
        '/ragflow-pipeline': 'projects:pwcRag',
        '/lexaday': 'projects:lexaday',
        '/dealtracker': 'projects:dealtracker',
        '/scrollytelling': 'projects:scrollytelling',
        '/early': 'projects:early',
        '/aipersonalarchive': 'projects:searchstory',
      }[this.$route.path] || '';
    },
    routeTransitionName() {
      if (isGeneratedViewPath(this.$route.path)) return 'view-compose';
      return ['/research', '/projects', '/fragments'].includes(this.$route.path)
        ? 'fade-slide'
        : 'route-fade';
    }
  },
  watch: {
    '$route.query.preview'(value) {
      this.applyPreviewScrollContainment(value === '1');
    },
    '$route.path'(path, previousPath) {
      if (this.mobileMenuOpen) this.closeMobileMenu({ restoreFocus: false });
      if (previousPath === '/' && path !== '/') {
        this.$nextTick(this.resetIntroChromeStyles);
      }
    },
    isCv(onCv, wasCv) {
      if (this._cvChromeRevealTimer) {
        clearTimeout(this._cvChromeRevealTimer);
        this._cvChromeRevealTimer = null;
      }
      if (onCv) {
        // Hide the chrome the moment the route changes, before the page
        // transition runs, so the header never flashes on the way in.
        this.cvChromeHidden = true;
        this.pauseMusicForCv();
      } else if (wasCv || this.cvChromeHidden) {
        this._cvChromeRevealTimer = setTimeout(() => {
          this._cvChromeRevealTimer = null;
          if (!this.isCv) {
            this.cvChromeHidden = false;
            this.$nextTick(() => this.scheduleNavTabsLayout({ retries: 4 }));
          }
        }, 280);
      }
    }
  },
  mounted() {
    if (!this.initialChromeReady && !this.isCv) {
      this.$nextTick(() => {
        const header = this.$el.querySelector('.header');
        const footer = this.$el.querySelector('.footer');
        const reduceMotion = window.matchMedia
          && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (reduceMotion) {
          this.initialChromeReady = true;
        } else {
          [header, footer].forEach((element) => {
            if (!element) return;
            element.style.opacity = '0';
            element.style.transform = element === header ? 'translateY(-8px)' : 'translateY(8px)';
          });
          this.initialChromeReady = true;
          this.$nextTick(() => {
            this._initialChromeAnimations = [
              animate(header, { opacity: [0, 1], transform: ['translateY(-8px)', 'translateY(0px)'] }, { type: 'spring', bounce: 0, duration: 0.42 }),
              animate(footer, { opacity: [0, 1], transform: ['translateY(8px)', 'translateY(0px)'] }, { type: 'spring', bounce: 0, duration: 0.46, delay: 0.08 }),
            ];
          });
        }
      });
    }
    this._removeViewOriginGuard = this.$router.beforeEach((to, from) => {
      // Header tabs are top-level navigation: entering a page through a tab
      // clears any pending origin so no back control follows the visitor.
      const tabNavigation = consumeTabNavigation();
      if (tabNavigation) {
        clearSiteOrigin();
      } else if (
        from.matched.length > 0
        && to.path !== from.path
        && !isGeneratedViewPath(to.path)
        && !isGeneratedViewPath(from.path)
      ) {
        // Any other cross-route jump records where the visitor came from and
        // their exact scroll position, so the destination can offer a precise
        // return. View pages keep their own origin flow and are excluded.
        setSiteOrigin({
          route: from.fullPath,
          label: siteOriginLabel(from),
          scrollY: window.scrollY,
        });
      }
      const enteringView = isGeneratedViewPath(to.path) && !isGeneratedViewPath(from.path);
      // A fresh full load straight into a View (from.matched is empty) has no
      // in-app origin to record; the View page falls back to its ?from query.
      if (enteringView && from.matched.length > 0) {
        setViewOriginRoute(from.fullPath);
        const component = from.matched[from.matched.length - 1]?.components?.default;
        const componentName = component?.name || component?.__name || '';
        this.viewOriginCache = componentName ? [componentName] : [];
      } else if (!isGeneratedViewPath(to.path) && !isGeneratedViewPath(from.path)) {
        this.viewOriginCache = [];
      }
      return true;
    });
    this._removeViewReturnHook = this.$router.afterEach(() => {
      // History state is available as soon as navigation commits. Sync before
      // the destination renders so its own back link never flashes beside the
      // View return control.
      if (window.history.state && window.history.state.forward) {
        // A back/forward traversal reuses an existing history entry; it is not
        // a fresh jump, so a page reached through the browser buttons keeps no
        // misleading back control.
        clearSiteOrigin();
      }
      this.syncViewReturnState();
      this.syncSiteBackState();
      this.$nextTick(this.syncViewReturnState);
      this.$nextTick(this.syncSiteBackState);
    });
    this.syncViewReturnState();
    this.syncSiteBackState();
    this.applyPreviewScrollContainment(this.previewMode);
    this._cleanupMediaRails = initCircularMediaRails();
    this.script1 = document.createElement('script');
    this.script1.src = '/assets/js/default.js';
    this.script1.async = true;
    document.body.appendChild(this.script1);
    this.script2 = document.createElement('script');
    this.script2.src = '/assets/js/theme-toggle.js';
    this.script2.async = true;
    document.body.appendChild(this.script2);
    this.$nextTick(this.setupDockControlSync);
    if (this.isCv) {
      this.cvChromeHidden = true;
      this.$nextTick(this.pauseMusicForCv);
    }
    this._onScroll = this.handleScroll;
    window.addEventListener('scroll', this._onScroll, { passive: true });
    this.handleScroll();

    this._onDirectHomeNavRevealed = () => {
      this.directHomeNavHidden = false;
      this.$nextTick(() => {
        this.refreshMarginDockThreshold();
        this.updateMarginDock();
      });
    };
    window.addEventListener('home-direct-nav-revealed', this._onDirectHomeNavRevealed);
    this._onOpenSiteAsk = () => this.$refs.search?.openAsk('');
    window.addEventListener('open-site-ask', this._onOpenSiteAsk);
    this._onOpenSiteView = () => this.$refs.search?.openView('');
    window.addEventListener('open-site-view', this._onOpenSiteView);
    this._onOpenSiteSearch = () => {
      const palette = this.$refs.search;
      if (!palette) return;
      palette.openPalette('site_button');
      palette.setMode('search');
    };
    window.addEventListener('open-site-search', this._onOpenSiteSearch);
    this._onAiCompletion = (event) => this.showAiCompletion(event.detail);
    window.addEventListener('site-ai-complete', this._onAiCompletion);
    this._onViewJob = (event) => this.handleViewJob(event.detail);
    window.addEventListener('site-view-job', this._onViewJob);
    this._onViewProgressInline = (event) => {
      const delta = Number(event.detail?.delta) || 0;
      this.viewProgressInlineCount = Math.max(0, this.viewProgressInlineCount + delta);
    };
    window.addEventListener('site-view-progress-inline', this._onViewProgressInline);
    const savedViewJob = loadViewJob();
    if (savedViewJob) {
      if (savedViewJob.status === 'complete') {
        this.adoptCompletedView(savedViewJob.payload, savedViewJob);
      } else {
        this.viewJobNotice = savedViewJob;
        this.resumeDetachedViewJob(savedViewJob);
      }
    }
    this._onResize = () => {
      if (window.innerWidth > 1100 && this.mobileMenuOpen) this.closeMobileMenu({ restoreFocus: false });
      this.scheduleNavTabsLayout();
      this.updateMarginDock({ instant: true, refreshThreshold: true });
    };
    window.addEventListener('resize', this._onResize, { passive: true });
    this._onMobileMenuKeydown = (event) => {
      if (!this.mobileMenuOpen) return;
      if (event.key === 'Escape') this.closeMobileMenu();
      if (event.key === 'Tab') this.trapMobileMenuFocus(event);
    };
    window.addEventListener('keydown', this._onMobileMenuKeydown);
    this.$nextTick(() => {
