            <div class="home-ask-followups-list">
              <button
                v-for="q in followUpQuestions"
                :key="q"
                type="button"
                class="home-ask-followup"
                @click="askFollowUp(q)"
              >{{ q }}</button>
            </div>
          </div>

          <div v-if="(askMapVisible || askBusy) && !viewBusy" class="home-ask-map-shell">
            <EmbeddingMap
              ref="homeAskMap"
              class="home-ask-map"
