              fit-stage
              initial-view-mode="3d"
              :monochrome="true"
              :show-controls="false"
              :show-view-toggle="false"
              :show-caption="false"
              :show-hits="false"
              :allow-navigation="homeAskMapNavigable"
              wheel-zoom-requires-pinch
              @ready="syncHomeAskMap"
            />
          </div>
        </div>
        </div>
      </div>
    </section>
    </div>

    <section class="home-current-panel" aria-labelledby="homeCurrentTitle">
      <div class="home-section-eyebrow"><span>Currently</span><i aria-hidden="true"></i></div>
      <h2 id="homeCurrentTitle">Current focus</h2>
