</template>

<script>
    import EmbeddingMap from './EmbeddingMap.vue';
    import ViewComposeProgress from './view/ViewComposeProgress.vue';
    import TextShimmerWave from './ui/TextShimmerWave.vue';
    import AskActions from './ui/AskActions.vue';
    import ArrowUpRightIcon from './ui/ArrowUpRightIcon.vue';
    import { animate } from 'motion';
    import { askConfigured, askStream, askErrorMessage } from '../utils/askSite';
    import { ASK_SAMPLE_PROMPTS, HOME_ASK_INTRO_PROMPT } from '../utils/askPrompts';
    import { currentlyItems } from '../data/currently';
    import { semanticTopK } from '../utils/semanticSearch';
    import {
        allAskContexts,
        askAnswerFollowUps,
        citedSourcesFromAnswer,
        cleanAskAnswer,
        cleanAskContextText,
        groundAskFollowUps,
        askViewRouting,
        askViewOffer,
        looksLikeViewBuildRequest,
        loadSearchItems,
        sourceDisplayTitle,
        takeRetrievalTrace,
    } from '../utils/askRetrieval';
    import { askActionsForDisplay, renderAskAnswerLinks } from '../utils/askActions';
    import { logAskClient, logEvent, newAskContext, newId, sessionId } from '../utils/askTelemetry';
    import {
        loadAskSession,
        addAskTurn,
        setAskView,
        setAskOrigin,
        recentAskTurns,
        recentDuplicateViewQuestion,
    } from '../utils/askSession';
    import {
        beginViewCompose,
        developViewDelay,
        DEVELOP_VIEW_ROUTE,
        endViewCompose,
        isDevelopMode,
        isViewComposing,
        requestView,
    } from '../utils/viewSite';
    import { candidatesForView } from '../utils/viewRetrieval';
    import { sanitizeViewResponse, validateViewResponse } from '../utils/viewValidation';
    import { settleScrollToId } from '../utils/anchorLanding';

    const HOME_ASK_STORAGE_KEY = 'homeAskState:v1';
    let homeAskMemory = null;

    function compactAskSources(sources) {
        return (sources || []).map((s) => ({
            id: s.id,
            route: s.route,
            anchor: s.anchor || '',
            page: s.page,
            title: s.title,
        }));
    }

    function readHomeAskState() {
        if (homeAskMemory) return homeAskMemory;
        if (typeof window === 'undefined' || !window.sessionStorage) return null;
        try {
            const raw = window.sessionStorage.getItem(HOME_ASK_STORAGE_KEY);
            homeAskMemory = raw ? JSON.parse(raw) : null;
            return homeAskMemory;
        } catch (err) {
            return null;
        }
    }

    function writeHomeAskState(state) {
        homeAskMemory = state;
        if (typeof window === 'undefined' || !window.sessionStorage) return;
        try {
            window.sessionStorage.setItem(HOME_ASK_STORAGE_KEY, JSON.stringify(state));
        } catch (err) {
            // Storage can be unavailable in private modes; in-memory state still covers route switches.
        }
    }

    function collectViewSourceIds(view) {
        const ids = [];
        for (const section of (view && view.sections) || []) {
            for (const block of (section && section.blocks) || []) {
                if (block && block.source_id) ids.push(block.source_id);
                if (block && block.source_ids) ids.push(...block.source_ids);
            }
        }
        return [...new Set(ids)];
    }

    export default {
        name: 'IndexPage',
        components: { ArrowUpRightIcon, AskActions, EmbeddingMap, TextShimmerWave, ViewComposeProgress },
        data() {
            return {
                scriptModule: null,
                askText: '',
                askFocused: false,
                askComposing: false,
                askAnswer: '',
                askSources: [],
                askBusy: false,
                askError: '',
                askStatus: '',
                askMapVisible: false,
                askMapHits: [],
                askMapLabel: '',
                askMapFinalized: false,
                askIntroPrompt: HOME_ASK_INTRO_PROMPT,
                askQuestions: ASK_SAMPLE_PROMPTS,
                askQIndex: -1,
                askRotate: null,
                homeScene: null,
                currentItems: currentlyItems,
                focusItems: [
                    currentlyItems.find((item) => item.id === 'location'),
                    currentlyItems.find((item) => item.id === 'structure-settles-thought'),
                    {
                        id: 'view',
                        title: 'View',
                        subtitle: 'Project on AI interface',
                        route: '/projects',
                        anchor: 'searchstory',
                    },
                ].filter(Boolean),
                siteIndexItems: [
                    { label: 'About', route: '/about' },
                    { label: 'Study', route: '/education' },
                    { label: 'Work', route: '/experience' },
                    { label: 'Research', route: '/research' },
                    { label: 'Builds', route: '/projects' },
                    { label: 'Fragments', route: '/fragments' },
                    { label: 'Views', route: '/views' },
                ],
                homeIntroStage: 0,
                homeEntranceReady: false,
                hoveredSourceId: null,
                previewStyle: null,
                // null = AI follow-ups not grounded yet; [] = grounded, none passed.
                groundedFollowUps: null,
                viewOfferVisible: false,
                returnViewAvailable: false,
                viewBusy: false,
                viewStartedAt: 0,
                viewError: '',
                mobileAskInputDocked: false,
            };
        },
        computed: {
            externalComposeActive() {
                return isViewComposing() && !this.viewBusy;
            },
            // Idle: cycle through real example questions in a separate overlay so
            // each change can fade instead of snapping like a native placeholder.
            askPromptText() {
                if (this.askFocused) return 'Ask anything about Henry…';
                if (this.askQIndex < 0) return this.askIntroPrompt;
                return this.askQuestions[this.askQIndex];
            },
            // Treat an in-progress IME composition (pinyin not yet committed) as "not empty",
            // so the placeholder hides the moment the user starts typing — otherwise it stays
            // up and overlaps the characters being composed in the input.
            inputEmpty() {
                return !this.askText && !this.askComposing;
            },
            showExamplePrompt() {
                return !this.askFocused && this.inputEmpty;
            },
            askAnswerText() {
                return cleanAskAnswer(this.askAnswer);
            },
            askAnswerHtml() {
                return renderAskAnswerLinks(this.askAnswerText);
            },
            askActionsList() {
                return askActionsForDisplay(this.askAnswer, this.viewOfferVisible ? 'offer' : 'none');
            },
            viewOffer() {
                return askViewOffer(this.askAnswer);
            },
            homeCitedSources() {
                return citedSourcesFromAnswer(this.askAnswer, this.askSources);
            },
            askErrorText() {
                return askErrorMessage();
            },
            homeAskMapNavigable() {
                // Clickable once the request settles, whether it produced an answer
                // or errored out: the map still holds the retrieved passages, so the
                // visitor can jump into them even when generation failed.
                return !this.askBusy && (!!this.askAnswerText || !!this.askError);
            },
            homeAskEngaged() {
                return !!(
                    this.askBusy
                    || this.askAnswerText
                    || this.askError
                    || this.askMapVisible
                    || this.viewBusy
                    || this.viewError
                );
            },
            // Hovering a cited source peeks at its passage without leaving the page.
            sourcePreview() {
                if (!this.hoveredSourceId) return null;
                const s = this.homeCitedSources.find((x) => x.id === this.hoveredSourceId);
                if (!s) return null;
                const text = cleanAskContextText(s.body || '').replace(/\s+/g, ' ').trim();
                const snippet = text
                    ? (text.length > 230 ? `${text.slice(0, 230).trim()}…` : text)
                    : 'Open the passage to read it.';
                return { id: s.id, page: s.page, title: s.title, snippet };
            },
            // A small set of next questions: deepen into the cited passages, then
            // fall back to the general pool. One answer becomes a short exploration.
            followUpQuestions() {
                if (this.askBusy || !this.askAnswerText) return [];
                // Only show the model's questions for this answer after they
                // have been grounded against the site's own retrieval index.
                const rawAiFollowUps = askAnswerFollowUps(this.askAnswer);
                if (this.groundedFollowUps !== null) {
                    return this.groundedFollowUps;
                }
                return rawAiFollowUps;
            },
        },
        watch: {
            hoveredSourceId(id) {
                this.positionSourcePreview(id);
            },
            askText: 'persistHomeAskState',
            askAnswer: 'persistHomeAskState',
            askSources: {
                handler: 'persistHomeAskState',
                deep: true,
            },
            askError: 'persistHomeAskState',
            askStatus: 'persistHomeAskState',
            askMapVisible: 'persistHomeAskState',
            askMapHits: {
                handler: 'persistHomeAskState',
                deep: true,
            },
            viewOfferVisible: 'persistHomeAskState',
            homeAskEngaged() {
                this.$nextTick(this.scheduleMobileAskDockUpdate);
            },
        },
        created() {
            this.restoreHomeAskState();
            this.syncReturnViewState();
        },
        async mounted() {
            this._isUnmounted = false;
            this._askSeq = 0;
            this._viewSeq = 0;
            this._onHomeAskReady = this.startAskRotation;
            this._onHomeSceneChange = (event) => {
                this.homeScene = event.detail || null;
            };
            this._onHomeIntroStage = (event) => {
                const stage = Number(event.detail && event.detail.stage);
                if (Number.isFinite(stage)) this.homeIntroStage = stage;
            };
            window.addEventListener('home-ask-ready', this._onHomeAskReady);
            window.addEventListener('home-scene-change', this._onHomeSceneChange);
            window.addEventListener('home-intro-stage', this._onHomeIntroStage);
            // Scrolling away the pointer's anchor hides the hover preview
            // immediately, so it never floats at a stale position.
            this._onAnyScroll = () => {
                if (this.hoveredSourceId) this.hoveredSourceId = null;
                this.scheduleMobileAskDockUpdate();
            };
            window.addEventListener('scroll', this._onAnyScroll, { capture: true, passive: true });
            this._onHomeResize = () => {
                this.scheduleMobileAskDockUpdate();
                this.syncHomeMotionForViewport();
                this.syncMobileHeroLayout();
            };
            window.addEventListener('resize', this._onHomeResize, { passive: true });
            this.$nextTick(() => {
                this.startHomeEntrance();
                this.syncHomeMotionForViewport();
            });
            this.$nextTick(this.syncMobileHeroLayout);
            if (document.fonts && document.fonts.ready) {
                document.fonts.ready.then(() => this.syncMobileHeroLayout()).catch(() => {});
            }
            // Dynamically import the script when the component is mounted
            this.scriptModule = await import('../assets/js/home.js');
            if (this.scriptModule && this.scriptModule.initScript) {
                this.scriptModule.initScript();
            }
            // Restored ask state is compacted for storage (no source bodies);
            // refill them from the search index so hover previews work again.
            this.rehydrateAskSources();
            if (this.askAnswer) this.groundAiFollowUps(this._askSeq);
            this.$nextTick(this.scheduleMobileAskDockUpdate);
        },
        unmounted() {
            this._isUnmounted = true;
            // Clean up the script when the component is unmounted
            if (this._homeAnims) {
                this._homeAnims.forEach((animation) => animation.stop());
                this._homeAnims.clear();
            }
            if (this.scriptModule && this.scriptModule.cleanupScript) {
                this.scriptModule.cleanupScript();
            }
            this.scriptModule = null; // Optionally, clear the reference to the module
            if (this._onHomeAskReady) window.removeEventListener('home-ask-ready', this._onHomeAskReady);
            if (this._onHomeSceneChange) window.removeEventListener('home-scene-change', this._onHomeSceneChange);
            if (this._onHomeIntroStage) window.removeEventListener('home-intro-stage', this._onHomeIntroStage);
            if (this._onAnyScroll) window.removeEventListener('scroll', this._onAnyScroll, { capture: true, passive: true });
            if (this._onHomeResize) window.removeEventListener('resize', this._onHomeResize);
            if (this._mobileAskDockFrame) cancelAnimationFrame(this._mobileAskDockFrame);
            if (this._mobileAskDockAnimation) this._mobileAskDockAnimation.stop();
            if (this._homeSectionObserver) this._homeSectionObserver.disconnect();
            if (this._homeEntranceTimers) {
                this._homeEntranceTimers.forEach((timer) => clearTimeout(timer));
                this._homeEntranceTimers.clear();
            }
            if (this.askRotate) clearInterval(this.askRotate);
            if (this._homeAskMapFinalTimer) clearTimeout(this._homeAskMapFinalTimer);
            if (this.askBusy) {
                this.askBusy = false;
                this.askStatus = this.askAnswer ? '' : 'Paused.';
                this.persistHomeAskState();
            }
        },
        methods: {
            homeEntranceDelay(callback, delay) {
                if (!this._homeEntranceTimers) this._homeEntranceTimers = new Set();
                const timer = window.setTimeout(() => {
                    this._homeEntranceTimers.delete(timer);
                    if (!this._isUnmounted) callback();
                }, delay);
                this._homeEntranceTimers.add(timer);
                return timer;
            },
            animateHomeEntranceElement(element, keyframes, options) {
                if (!element) return null;
                let animation;
                const suppliedOnComplete = options && options.onComplete;
                const cleanup = () => {
                    element.style.removeProperty('opacity');
                    element.style.removeProperty('transform');
                    this.untrackHomeAnim(animation);
                    if (suppliedOnComplete) suppliedOnComplete();
                };
                animation = this.trackHomeAnim(animate(element, keyframes, {
                    ...options,
                    onComplete: cleanup,
                }));
                return animation;
            },
            typeHomeSubtitle(element) {
                if (!element) return;
                const text = 'I explore.\nI try to understand.\nI build from there.';
                element.replaceChildren();
                element.style.visibility = 'visible';
                element.style.opacity = '1';
                const characters = [...text].map((character) => {
                    const span = document.createElement('span');
                    span.className = 'typed';
                    span.textContent = character;
                    span.style.visibility = 'hidden';
                    element.appendChild(span);
                    return span;
                });
                const caret = document.createElement('span');
                caret.className = 'home-type-caret';
                caret.setAttribute('aria-hidden', 'true');
                element.appendChild(caret);
                let index = 0;
                const reveal = () => {
                    if (index >= characters.length) {
                        caret.classList.add('is-finished');
                        this.homeEntranceDelay(() => caret.remove(), 520);
                        return;
                    }
                    const span = characters[index];
                    span.style.visibility = 'visible';
                    caret.style.left = `${span.offsetLeft + span.offsetWidth}px`;
                    caret.style.top = `${span.offsetTop + Math.max(1, (span.offsetHeight - caret.offsetHeight) / 2)}px`;
                    const character = text[index];
                    index += 1;
                    // Read at a human, deliberate pace: punctuation and line
                    // breaks pause longer so each sentence settles.
                    const pause = /[.!?]/.test(character) ? 360 : (character === '\n' ? 80 : 30);
                    this.homeEntranceDelay(reveal, pause);
                };
                reveal();
            },
            startHomeEntrance() {
                const root = this.$el;
                if (!root) return;
                const reduceMotion = this.homeReduceMotion();
                const isMobile = window.innerWidth <= 760;
                const hero = root.querySelector('.home-hero-panel');
