<template>
  <div class="view-source">
    <template v-if="!source">
      <div class="view-source-missing">This source is currently unavailable.</div>
    </template>
    <template v-else>
      <figure v-if="presentation === 'quote'" class="view-quote">
        <blockquote>
          <p v-for="(text, index) in selectedParts" :key="`${index}-${text}`">{{ text }}</p>
        </blockquote>
        <figcaption>{{ sourceTitle }}</figcaption>
      </figure>
      <ViewCitation
        v-else-if="presentation === 'cite'"
        :source="source"
        :texts="selectedParts"
        @open-source="$emit('open-source', source)"
      />
      <section v-else-if="presentation === 'component'" class="view-origin-frame">
        <div class="origin-content">
          <ViewOriginalBlock
            :source="source"
            :block="block"
            @source-error="$emit('source-error', block.source_id)"
          />
        </div>
        <ViewCitation footer :source="source" @open-source="$emit('open-source', source)" />
      </section>
      <div v-else-if="presentation === 'excerpt'" class="view-excerpt">
        <p class="view-source-label">{{ sourceTitle }}</p>
        <p v-for="(text, index) in selectedParts" :key="`${index}-${text}`">{{ text }}</p>
      </div>
      <div v-else-if="presentation === 'card'" class="view-card">
        <div class="view-card-kicker">{{ kindLabel }}</div>
        <h3 class="view-card-title">{{ sourceTitle }}</h3>
        <p v-if="entityMeta" class="view-card-meta">{{ entityMeta }}</p>
        <p v-if="entityDescription" class="view-card-desc">{{ entityDescription }}</p>
        <div v-if="source.media && source.media.length" class="view-card-media">
          <img :src="source.media[0].src" :alt="sourceTitle" loading="lazy" decoding="async" @error="$emit('source-error', block.source_id)">
        </div>
      </div>
      <div v-else-if="presentation === 'media'" class="view-media">
        <p class="view-source-label">{{ sourceTitle }}</p>
        <img v-for="m in source.media" :key="m.src" :src="m.src" :alt="sourceTitle" loading="lazy" decoding="async" @error="$emit('source-error', block.source_id)">
      </div>
      <section v-else-if="presentation === 'interactive' || presentation === 'embed'" class="view-origin-frame view-rich-wrap">
        <div class="origin-content">
          <ViewArchivedSnapshot
            v-if="source.snapshot_html && !renderLiveRichBlock"
            :html="source.snapshot_html"
            :block-id="block.source_id"
            :snapshot-source="source"
            :current-source="currentSource"
          />
          <ViewRichBlock v-else :block-id="block.source_id" :source="source" />
          <p v-if="renderLiveRichBlock && richSourceChanged" class="snapshot-state"><span aria-hidden="true">◷</span> Shown as it appeared when this View was created</p>
        </div>
        <ViewCitation footer :source="source" @open-source="$emit('open-source', source)" />
      </section>
      <div v-if="!['cite', 'component', 'interactive', 'embed'].includes(presentation)" class="view-provenance">
        <button v-if="provenance.route" type="button" @click="$emit('open-source', source)">
          Read original in {{ sourcePageLabel(provenance) }}
          <ArrowUpRightIcon />
        </button>
        <span v-else>{{ sourcePageLabel(provenance) }}</span>
      </div>
    </template>
  </div>
</template>

<script>
import ViewRichBlock from './ViewRichBlock.vue';
import ViewOriginalBlock from './ViewOriginalBlock.vue';
import ViewCitation from './ViewCitation.vue';
import ViewArchivedSnapshot from './ViewArchivedSnapshot.vue';
import { sourceDisplayTitle } from '../../utils/askRetrieval';
import { sourceFingerprint } from '../../utils/viewSnapshotCompare';
import { decodeViewText } from '../../utils/viewText';
import { sourcePageLabel } from '../../utils/viewSourceTarget';

export default {
  name: 'ViewSourceBlock',
  components: { ViewArchivedSnapshot, ViewCitation, ViewOriginalBlock, ViewRichBlock },
  props: {
    block: {
      type: Object,
      required: true,
    },
    source: {
      type: Object,
      default: null,
    },
    currentSource: {
      type: Object,
      default: null,
    },
  },
  emits: ['open-source', 'source-error'],
  data() {
    return { richSourceChanged: false };
  },
  computed: {
    selectedParts() {
      if (!this.source) return [];
      const parts = Array.isArray(this.source.parts) ? this.source.parts : [];
      const selected = !this.block.part_indices || !this.block.part_indices.length
        ? (parts.length ? [parts[0]] : [])
        : this.block.part_indices.map((i) => parts[i]).filter((text) => text != null);
      return selected.map(decodeViewText);
    },
    presentation() {
      return this.block.presentation || 'excerpt';
    },
    sourceTitle() {
      return sourceDisplayTitle(this.source);
    },
    kindLabel() {
      const labels = {
        prose: 'From the site',
        fragment: 'Fragment',
        project: 'Project',
        experience: 'Experience',
        education: 'Education',
        publication: 'Research',
      };
      return labels[this.source?.view_kind] || 'Source';
    },
    provenance() {
      if (!this.source) return { page: 'Original source', route: null };
      return {
        page: this.source.page || this.sourceTitle,
        route: this.source.route || null,
        anchor: this.source.anchor || '',
      };
    },
    entity() {
      return this.source && this.source.entity;
    },
    entityMeta() {
      if (!this.entity) return '';
      if (this.entity.kind === 'publication') return [this.entity.period, this.entity.status].filter(Boolean).join(' · ');
      if (this.entity.kind === 'project') return this.entity.period || '';
      if (this.entity.kind === 'experience') return [this.entity.organisation, this.entity.period].filter(Boolean).join(' · ');
      if (this.entity.kind === 'fragment') return this.entity.teaser || '';
      return '';
    },
    entityDescription() {
      return this.source && this.source.parts && this.source.parts[0] ? this.source.parts[0] : '';
    },
    renderLiveRichBlock() {
      const blockId = this.block?.source_id || '';
      return [
        'interactive.travels.globe',
        'interactive.about.exploration-paths',
        'interactive.search.system-paths',
        'interactive.search.embedding-map',
        'interactive.search.retrieval-lab',
        'interactive.search.view-composer',
      ].includes(blockId) || blockId.startsWith('interactive.travels.place.');
    },
  },
  watch: {
    source: 'compareLiveRichSource',
    currentSource: 'compareLiveRichSource',
  },
  mounted() {
    this.compareLiveRichSource();
  },
  methods: {
    sourcePageLabel,
    async compareLiveRichSource() {
      if (!this.renderLiveRichBlock) return;
      if (!this.currentSource) {
        this.richSourceChanged = true;
        return;
      }
      const current = await sourceFingerprint(this.currentSource);
      const saved = this.source?.source_fingerprint || await sourceFingerprint(this.source);
      this.richSourceChanged = current !== saved;
    },
  },
};
</script>

